it('rejects input missing a required field with a ToolResponse naming the field and without calling the executor', async () => {
  const executor = jest.fn(async (input: Record<string, unknown>) => String(input.location));
  const locationSchema = {required: ['location'], properties: {location: {type: 'string'}}, type: 'object'};
  const registry = new ToolRegistry();
  registry.register({inputSchema: locationSchema, description: 'Forecast by city', name: 'forecast'}, executor);

  const {result} = await registry.execute('forecast', {});

  expect([executor.mock.calls, result]).toEqual([[], 'Invalid input for tool "forecast": location is required']);
});

